func testAccChronicleRequestTemplate_chronicleRequesttemplateBasicExample(context map[string]interface{}) string {
	return acctest.Nprintf(`
resource "google_chronicle_request_template" "sample" {
  provider = google-beta
  location = "us"
  instance = "%{chronicle_id}"

  display_name      = "Access Request Form"
  visual_family     = "Authentication"
  environments      = ["Default Environment"]
  allow_description = false

  event_field_definitions {
    name      = "user.email"
    watermark = "user@example.com"
    type      = "EMAIL"
  }
}
`, context)
}

